class Solution:
    def maximumOr(self, nums: List[int], k: int) -> int:
        n = len(nums)
        if n == 1:
            return nums[0] << k

        prefix = [0] * n
        prefix[1] = nums[0]
        for i in range(2, n):
            prefix[i] = prefix[i - 1] | nums[i - 1]

        suffix = [0] * n
        suffix[-2] = nums[-1]
        for i in range(n - 3, -1, -1):
            suffix[i] = suffix[i + 1] | nums[i + 1]

        max_val = 0
        for i in range(n):
            shifted = nums[i] << k
            result = prefix[i] | shifted | suffix[i]
            if result > max_val:
                max_val = result

        return max_val

