class Solution:
    def maxStrength(self, nums: List[int]) -> int:
        if len(nums) == 1:
            return nums[0]

        positives = [x for x in nums if x > 0]
        negatives = sorted([x for x in nums if x < 0])
        odd_count = len(negatives) % 2 != 0

        if odd_count:
            negatives.pop()

        chosen = positives + negatives
        if not chosen:
            chosen = [max(nums)]

        prod = 1
        for x in chosen:
            prod *= x

        return prod

