class Solution:
    def semiOrderedPermutation(self, nums: List[int]) -> int:
        n = len(nums)
        idx1 = nums.index(1)
        idxn = nums.index(n)

        swaps = idx1 + (n - 1 - idxn)
        if idx1 > idxn:
            swaps -= 1

        return swaps

