class Solution:
    def minCost(self, nums: List[int], x: int) -> int:
        n = len(nums)
        min_costs = list(nums)
        ans = sum(min_costs)

        for k in range(1, n):
            for i in range(n):
                min_costs[i] = min(min_costs[i], nums[(i - k) % n])
            ans = min(ans, k * x + sum(min_costs))

        return ans

class Solution:
    def minimumSum(self, n: int, k: int) -> int:
        seen = set()
        total = 0
        curr = 1
        while len(seen) < n:
            if (k - curr) not in seen:
                seen.add(curr)
                total += curr
            curr += 1
        return total

