class Solution:
    def sumImbalanceNumbers(self, nums: List[int]) -> int:
        n = len(nums)
        total = 0
        for i in range(n):
            seen = {nums[i]}
            curr = 0
            for j in range(i + 1, n):
                x = nums[j]
                if x not in seen:
                    seen.add(x)
                    has_prev = (x - 1) in seen
                    has_next = (x + 1) in seen
                    if has_prev and has_next:
                        curr -= 1
                    elif not has_prev and not has_next:
                        curr += 1
                total += curr
        return total
